4: [JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
5: public sealed class StudentSearchInput
6: {
7:     public string StudentNo { get; set; } = "";
8:     public string Name { get; set; } = "";
9:     public string Kana { get; set; } = "";
10:     public int? SchoolYear { get; set; }
11:     public string? GradeCode { get; set; }
12:     public string? ClassId { get; set; }
13:     public bool UnassignedOnly { get; set; }
14:     public string[] StatusCodes { get; set; } = ["01","02"];
15:     public string? PrefectureCode { get; set; }
16:     public string PhoneNumber { get; set; } = "";
17:     public string? AdmissionFrom { get; set; }
18:     public string? AdmissionTo { get; set; }
19:     public SearchCriteria ToCriteria(int size,string key,string direction) => new() { StudentNo=StudentNo,StudentName=Name,StudentNameKana=Kana,
20:         SchoolYear=SchoolYear,GradeCode=GradeCode,ClassId=IdParser.Optional(ClassId,"SRC-006"),UnassignedOnly=UnassignedOnly,
21:         EnrollmentStatusCodes=StatusCodes,PrefectureCode=PrefectureCode,PhoneNumber=PhoneNumber,AdmissionFrom=AdmissionFrom,AdmissionTo=AdmissionTo,
22:         Page=1,PageSize=size,SortKey=key,SortDirection=direction };
23: }
24: [JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
25: public class ContextRequest { public string ContextId {get;set;}=""; public string ContextRevision {get;set;}=""; }
26: [JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
27: public sealed class SearchRequest : ContextRequest { public StudentSearchInput Criteria {get;set;}=new(); public int PageSize {get;set;}=20; public string SortKey {get;set;}="studentNo"; public string SortDirection {get;set;}="asc"; }
28: [JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
29: public sealed class PageRequest : ContextRequest { public int Page {get;set;}=1; public int PageSize {get;set;}=20; public string SortKey {get;set;}="studentNo"; public string SortDirection {get;set;}="asc"; }
30: [JsonUnmappedMemberHandling(JsonUnmappedMemberHandling.Disallow)]
31: public sealed class OptionsRequest { public string Usage {get;set;}="search"; public int? SchoolYear {get;set;} public string? GradeCode {get;set;} public string? StudentId {get;set;} public string? EnrollmentStatusCode {get;set;} public string? AdmissionDate {get;set;} public string? EnrollmentEndDate {get;set;} }
